import numpy as np

def sigmoid(z):
    return 1.0 / (1.0 + np.exp(-np.clip(z, -25, 25)))

def fit_logistic(X, y, lr=0.25, epochs=30):
    w = np.zeros(X.shape[1])
    b = 0.0
    for _ in range(epochs):
        p = sigmoid(X @ w + b)
        err = p - y
        w -= lr * (X.T @ err) / len(y)
        b -= lr * np.mean(err)
    return w, b
